#!/usr/bin/env python3
"""Render the measured RGBA optimization and its complete comparison matrix."""
import csv,html,json,math,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
E=ROOT/'docs/evidence/rgba-optimization'
def gm(xs):return math.exp(sum(math.log(x) for x in xs)/len(xs))
def main():
 d=json.loads((E/'results.json').read_text());rs=d['records'];meta=d['metadata'];summary=json.loads((E/'summary.json').read_text())
 assert len(rs)==92 and all(r['correctness']['before']['sha256']==r['correctness']['after']['sha256'] for r in rs)
 find=lambda name,mode:next(r for r in rs if r['group']=='main' and r['case']['name']==name and r['mode']==mode)
 selected=[find(n,'rgba') for n in ['rgb-none','gray-none','rgb-deflate','jpeg-smooth','webp-lossless'] if any(r['case']['name']==n and r['mode']=='rgba' for r in rs)]
 aggregate=[]
 for mode in ['native','scan','rgba','crop']:
  group=[r for r in rs if r['group']=='main' and r['mode']==mode]
  aggregate.append([mode,str(len(group)),f"{gm([r['statistics']['before']['median_ms']/r['statistics']['libtiff']['median_ms'] for r in group]):.2f}×",f"{gm([r['vs_libtiff'] for r in group]):.2f}×",f"{gm([r['speedup'] for r in group]):.2f}×"])
 def values(r):
  s=r['statistics'];return [r['case']['label']+' / '+r['mode'],*[f"{s[e]['median_ms']:.4f}" for e in ['before','after','libtiff']],f"{r['speedup']:.2f}×",f"{r['vs_libtiff']:.2f}×"]
 headers=['Input / operation','Before ms','After ms','4.7.1 ms','Speedup','After / 4.7.1']
 def table(h,rows):return '| '+' | '.join(h)+' |\n| '+' | '.join(['---']*len(h))+' |\n'+''.join('| '+' | '.join(row)+' |\n' for row in rows)
 def htable(h,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
 rgb=find('rgb-none','rgba');rgba=[r for r in rs if r['group']=='main' and r['mode']=='rgba']
 lead=f"Uncompressed RGB full RGBA improved {rgb['speedup']:.2f}×, from {rgb['statistics']['before']['median_ms']:.3f} to {rgb['statistics']['after']['median_ms']:.3f} ms. Across the 22 full-RGBA cases, the geometric-mean improvement is {gm([r['speedup'] for r in rgba]):.2f}×; the new reader takes {gm([r['vs_libtiff'] for r in rgba]):.2f}× as long as libtiff 4.7.1."
 changes=[
  'A new allocation-free Verus row kernel handles contiguous unsigned 8/16-bit RGB and grayscale, both grayscale polarities, native byte order, extra channels, selected alpha and horizontal mirroring. Common layouts specialize once per row. Direct sample loads replace generic read_word calls; RGB unassociated-alpha multiplication is fused into the row loop. Existing grayscale alpha presentation is preserved.',
  'The adapter borrows complete cached segments directly instead of allocating and copying a native row for each conversion. Rows still write to private RGBA storage; the final caller-buffer commit remains failure-atomic.',
  'Completely covered Deflate segments can use the existing one-pass native decoder when the decoded segment is at most 1 MiB and conservative single/cumulative allocation checks admit its scratch. Otherwise reads retain validation and bounded replay. This optional optimization preserves the old conservative work quota; it does not relax checksum, ending, crop or allocation checks.'
 ]
 scope='The new core proves exact row acceptance, output components and rounding, byte order, horizontal reversal, unchanged output on invalid arguments, suffix preservation and bounded termination. The C/FFI orchestration, allocation admission and caller-buffer commit remain tested ordinary Rust/C, not an end-to-end verified TIFF pipeline. No new trusted contract, unsafe core code or runtime native codec dependency was added. Packed bilevel/palette, separate-plane and CMYK/Lab/raw-YCbCr conversion still use existing conversion paths. Partial compressed reads still validate complete streams before exposing pixels.'
 tests=f"The complete crate passed {summary['proof']['verified']:,} proof obligations with zero errors and all {summary['negative_gates']} negative gates. All {summary['rust_tests']} Rust tests, {summary['core_python_tests']} core Python methods and {summary['c_tests']} C test methods passed; the complete C suite also passed ASan/UBSan. The original 31-image corpus, 20,000 deterministic core mutations and the oracle's own 108 upstream tests passed. C sanitizers do not instrument Rust; LeakSanitizer is disabled in this environment."
 correctness='All 92 before/after outputs match byte-for-byte, including JPEG. Against libtiff, 90 match exactly; two textured-JPEG cases retain a maximum difference of one 8-bit channel value. Independent new tests cover every 16-bit narrowing value, all 65,536 byte-value/alpha pairs, extra-channel selection, invalid arguments and output guards, mirrored crops, predicted full Deflate reads in both byte orders, tight cumulative-memory fallback and a corrupt later strip leaving the entire caller buffer untouched.'
 crop='Expanded tests also preserve the independently expected pixels for nonzero-column 16-bit crops. Both the prior and new adapter agree. Pinned 4.7.1 gtStripContig adds col_offset*samplesperpixel to a byte buffer without multiplying by bytes per sample; its output differs for these cases. Those cases therefore use an independent pixel oracle instead of adopting that offset behavior.'
 method=f"Measured {meta['utc']} on {meta['cpu_model']}, pinned CPU {meta['cpu']}. Each of the 92 workloads uses {meta['rounds']} randomized serial batches of at least {meta['milliseconds']:g} ms per engine, plus three separate file-backed RSS processes. The identical C consumer opens a fresh handle per operation; timing uses common memory callbacks and excludes file loading, output allocation, hashing and startup. The exact preserved baseline, current reader and pinned libtiff 4.7.1 were rebuilt. The reference uses zlib rather than libdeflate; its pinned JPEG build has SIMD disabled. LERC/WebP/Zstandard versions and all source, input, binary and proof hashes are in results.json. Main-suite geometric means exclude eight strip-height and six default-strip-chopping diagnostics. RSS includes caller storage and process overhead. Results are specific to this suite and host."
 reg=[r for r in rs if r['speedup']<1/1.1]
 regression='No main-run median slowdown exceeded 10%.' if not reg else 'Main-run median slowdowns exceeding 10%: '+', '.join(f"{r['case']['name']}/{r['mode']} ({r['group']}): {1/r['speedup']:.2f}×" for r in reg)+'.'
 if (E/'recheck.json').exists():
  checks=json.loads((E/'recheck.json').read_text())['records'];assert len(checks)==len(reg)
  persistent=[r for r in checks if r['speedup']<1/1.1]
  regression+=' Every such workload was rechecked with nine randomized 500 ms batches per engine. '+('None remained above 10%.' if not persistent else 'Remaining: '+', '.join(f"{r['case']}/{r['mode']}: {1/r['speedup']:.2f}×" for r in persistent)+'.')
 md='# RGBA row and segment optimization\n\n'+lead+'\n\n'+table(headers,[values(r) for r in selected])+'\n## Main-suite geometric means\n\n'+table(['Operation','Cases','Before / 4.7.1','After / 4.7.1','Speedup'],aggregate)+'\n'+regression+'\n\n## Changes and proof boundary\n\n'+'\n\n'.join(changes)+'\n\n'+scope+'\n\n## Validation\n\n'+tests+'\n\n'+correctness+'\n\n'+crop+'\n\n## Method and reproduction\n\n'+method+'\n\nRun `benchmarks/prepare-rgba-baseline.py`, the full proof/test gates, `benchmarks/prepare-reader.py`, `benchmarks/build-reader.sh`, then `benchmarks/rgba-optimization.py`. Raw measurements, full proof/gate logs, test logs and source hashes are in `docs/evidence/rgba-optimization/`; `results.csv` contains every workload. The source reverse patch restores and hash-checks the exact pre-RGBA reader. Earlier Deflate/LERC results remain in [reader-optimization.md](reader-optimization.md).\n'
 (ROOT/'docs/rgba-optimization.md').write_text(md)
 with (E/'results.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['group','case','mode','before_ms','after_ms','libtiff_ms','speedup','after_over_libtiff','before_rss_mib','after_rss_mib','libtiff_rss_mib'])
  for r in rs:
   s=r['statistics'];w.writerow([r['group'],r['case']['name'],r['mode'],*[s[e]['median_ms'] for e in ['before','after','libtiff']],r['speedup'],r['vs_libtiff'],*[s[e]['median_rss_mib'] for e in ['before','after','libtiff']]])
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RGBA optimization</title><style>body{background:#f5f6f8;color:#172330;font:16px/1.6 system-ui;margin:0}main{max-width:1120px;margin:auto;padding:48px 24px}h1{font-size:38px;line-height:1.2}h2{margin-top:36px}.lead{font-size:21px}.scroll{overflow:auto;border:1px solid #d8e0e6;border-radius:8px;background:white}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:10px 14px;text-align:right;white-space:nowrap;border-bottom:1px solid #e7ebee}td:first-child,th:first-child{text-align:left}th{background:#eaf0f4}select,input{padding:9px 12px;font:inherit;margin:0 8px 14px 0}.note{font-size:14px;color:#4d6170}li{margin:12px 0}.good{border-left:4px solid #25876e;padding:12px 20px;background:#e8f4ef}@media print{body{background:white}main{padding:0}input,select{display:none}}</style><main><p class="note">verified-tiff · measured optimization</p><h1>Faster full RGBA reads</h1>'''
 page+='<p class="lead">'+html.escape(lead)+'</p><p class="good">'+html.escape(correctness)+'</p><h2>Selected results</h2><p class="note">Median milliseconds. Speedup is before / after. After / 4.7.1 above one means slower.</p>'+htable(headers,[values(r) for r in selected])
 page+='<h2>Main-suite geometric means</h2>'+htable(['Operation','Cases','Before / 4.7.1','After / 4.7.1','Speedup'],aggregate)+'<p>'+html.escape(regression)+'</p><h2>What changed</h2><ol>'+''.join('<li>'+html.escape(x)+'</li>' for x in changes)+'</ol><p>'+html.escape(scope)+'</p><h2>Validation</h2><p>'+html.escape(tests)+'</p><p>'+html.escape(crop)+'</p>'
 page+='<h2>All 92 workloads</h2><label>Group <select id="group"><option value="">All</option><option>main</option><option>layout</option><option>defaults</option></select></label><label>Filter <input id="query" placeholder="e.g. rgba, deflate, crop"></label><div id="all">'+htable(['Group']+headers,[[r['group']]+values(r) for r in rs])+'</div><h2>Peak RSS</h2><p class="note">Median MiB across three separate file-backed processes. Includes caller storage and process overhead.</p>'+htable(['Input / operation','Before MiB','After MiB','4.7.1 MiB'],[[r['case']['label']+' / '+r['mode'],*[f"{r['statistics'][e]['median_rss_mib']:.2f}" for e in ['before','after','libtiff']]] for r in selected])+'<h2>Method and scope</h2><p>'+html.escape(method)+'</p><p class="note">The source archive includes raw samples, pixel hashes, proof and test receipts, reproducible baseline restoration and all 92 results in CSV.</p></main>'
 page+='''<script>const group=document.getElementById('group'),query=document.getElementById('query');function filter(){for(const row of document.querySelectorAll('#all tbody tr'))row.hidden=!!((group.value&&row.cells[0].textContent!==group.value)||!row.textContent.toLowerCase().includes(query.value.toLowerCase()));}group.addEventListener('change',filter);query.addEventListener('input',filter);</script></html>'''
 target=ROOT.parent/'output/rgba-optimization.html';target.parent.mkdir(exist_ok=True);target.write_text(page)
 print(lead);print(regression);print(target)
if __name__=='__main__':main()
